    "contact": "data-products@example.com"
  },

  "api": {
    "host": ">=1.4.0 <2.0.0",
    "controlProtocol": "1"
  },

  "runtime": {
    "kind": "oci",
    "entrypoint": ["/plugin/bin/plugin-server"],
    "platforms": ["linux/amd64", "linux/arm64"]
  },

