      "configSchema": "schemas/exporter-config.schema.json"
    }
  ],

  "lifecycle": {
    "loadTimeoutMs": 30000,
    "unloadTimeoutMs": 15000,
    "supportsStateTransfer": false
  },

  "permissions": {
    "datasets": ["report-result:read"],
    "secrets": [],
    "network": [],
    "objectStorage": ["exports:write"],
    "persistentState": false,
    "personallyIdentifiableData": false
  },

  "resources": {
    "cpuMillis": 500,
    "memoryMiB": 256,
    "temporaryStorageMiB": 128,
